CUR['app/src/main/java/com/particlesdevs/photoncamera/processing/processor/MotionV2CfaReconstruction.java']='76CAC4E7FE2B185068ADE3F34D5BB04FA60E81FFF3E05D3027897501A9764874'
CUR['app/src/main/java/com/particlesdevs/photoncamera/processing/processor/MotionV2Alignment.java']='80548631423555C5C104A76E5B5950FFB44C69008D85D47440C8E01D7A0B2BA8'
CUR['app/src/main/java/com/particlesdevs/photoncamera/processing/opengl/postpipeline/MotionV2CfaInput.java']='C3699054F6A25308576618754A2B5317AD387DD0E8A424435779934E0EE968F2'
declare -A PAYLOAD
PAYLOAD['app/src/main/assets/shaders/motionv2/direct_rgb_init.glsl']=''
