PAYLOAD['app/src/main/assets/shaders/motionv2/color_transform.glsl']=''
PAYLOAD['app/src/main/java/com/particlesdevs/photoncamera/processing/opengl/postpipeline/MotionV2Denoise.java']=''
PAYLOAD['app/src/main/assets/shaders/motionv2/denoise.glsl']=''
PAYLOAD['app/src/main/java/com/particlesdevs/photoncamera/processing/opengl/postpipeline/MotionV2Render.java']=''
PAYLOAD['app/src/main/assets/shaders/motionv2/render.glsl']=''
PAYLOAD['app/src/main/assets/shaders/motionv2/gainmap.glsl']=''
PAYLOAD['app/src/main/java/com/particlesdevs/photoncamera/processing/ultrahdr/MotionV2UltraHdr.java']=''
PAYLOAD['app/version.properties']='I1dlZCBBdWcgMDUgMjI6NTY6MDQgRURUIDIwMjYKVkVSU0lPTl9OQU1FPTAuOTcyNjQzNQpWRVJTSU9OX0JVSUxEPTI2NDM1Cg=='
declare -A NEWHASH
NEWHASH['app/src/main/assets/shaders/motionv2/direct_rgb_init.glsl']='8E0D3A176280C49D17094BC318382F9C1AF97C76FFFA85ACA7B19053F516C5C1'
NEWHASH['app/src/main/assets/shaders/motionv2/direct_rgb_accumulate.glsl']='A7BF945D386C881A9259A9626D2A7F69AE8A5DA998387248D484D91B9A50E221'
NEWHASH['app/src/main/java/com/particlesdevs/photoncamera/processing/opengl/postpipeline/MotionV2ColorTransform.java']='4D222AB51E82ADFDC136C4F3A21A562EDB85184CE3749CACE0AC760620120B63'
NEWHASH['app/src/main/assets/shaders/motionv2/color_transform.glsl']='642DDD94D9374C9792A652561AE82C67ADD73D1FB810551A9CC157FD15AAADF1'
NEWHASH['app/src/main/java/com/particlesdevs/photoncamera/processing/opengl/postpipeline/MotionV2Denoise.java']='C451D4D98BAEA223638CDA2CA116400881440A153720A358BF1C00D1AC381C20'
NEWHASH['app/src/main/assets/shaders/motionv2/denoise.glsl']='420BAB6F8D917BF8A37D5B6F5864080A1179C04AB90FBD51C0474E45898C3A1C'
NEWHASH['app/src/main/java/com/particlesdevs/photoncamera/processing/opengl/postpipeline/MotionV2Render.java']='97F897EAE0A4AB271B01AD468CBE4643E62D4C95254E15D8813D18446A48E65B'
NEWHASH['app/src/main/assets/shaders/motionv2/render.glsl']='FEBC6CCD70249EE036EEAD47C266DA4A3D7133209555CBCC1A584B1E3A066D7D'
NEWHASH['app/src/main/assets/shaders/motionv2/gainmap.glsl']='E93F72FDA4065C099AD0BC522ED9B137275EB0A51EF3C44B2468016CF97C9CC3'
NEWHASH['app/src/main/java/com/particlesdevs/photoncamera/processing/ultrahdr/MotionV2UltraHdr.java']='C3BEF060707E84BEEC343C701A7208B186F7E68A06C697C8D6504438F0A8AE68'
NEWHASH['app/version.properties']='C7D75FFDC1A56DF85FAA2185E89EB3DDB9F9EF957A05CCA518508091986FC7E3'

echo "======================================================================"
echo "26435 - EXACT 26430 SDR RECOVERY + LOW-FREQUENCY ULTRA HDR PROVENANCE"
echo "======================================================================"

echo "=== GATE 0: EXACT 26434 REGRESSION STATE ==="
[[ "$(git branch --show-current)" == "$BRANCH" ]] || fail "Wrong branch"
[[ "$(git rev-parse --short=8 HEAD)" == "$HEAD_SHORT" ]] || fail "Unexpected committed HEAD"
for rel in "${!CUR[@]}"; do
  [[ -f "$rel" ]] || fail "Missing lineage file: $rel"
  [[ "$(sha "$rel")" == "${CUR[$rel]}" ]] || fail "Current 26434 hash mismatch: $rel"
done
grep -q '^VERSION_NAME=0\.9726434$' "$VERSION" || fail "Not on 26434"
grep -q '^VERSION_BUILD=26434$' "$VERSION" || fail "Not on build 26434"

# All-frame handoff remains; this build intentionally does NOT add another motion algorithm.
grep -q 'IRIS_26431_MOTION_V2_ALL_FRAME_HANDOFF' "$HDRX" || fail "All-frame handoff missing"
grep -q 'targetFraction=1.0' "$HDRX" || fail "All-frame target missing"
grep -q 'globalGyroDiscard=false' "$HDRX" || fail "Global discard returned"

# Legacy Photon post graph remains bypassed.
grep -q 'exposureFusion=false esd=false ablc=false' "$POST" || fail "Legacy V2 bypass missing"
grep -q 'initial=false autoExposure=false' "$POST" || fail "Legacy tone bypass missing"
grep -q 'captureSharpening=false correctingFlow=false sharpen2=false' "$POST" || fail "Legacy sharpening bypass missing"

echo "PASS: exact 26434 regression state + all-frame routing proven"

echo "=== GATE 1: BACKUP BRANCH + PRE-EDIT PATCH ==="
SAFETY="$OUT/safety_26435_exact26430_sdr_lowfreq_hdr_$STAMP"
CAND="$SAFETY/candidate"
mkdir -p "$CAND"
BACKUP="backup/codespace-before-26435-exact26430-sdr-lowfreq-hdr-$STAMP"
git branch "$BACKUP"
git diff --binary HEAD -- app > "$SAFETY/pre_26435_working_tree.patch"

TARGETS=("$DINIT" "$DACC" "$COLORJ" "$COLORG" "$DENOISEJ" "$DENOISEG" "$RENDERJ" "$RENDERG" "$GAINMAP" "$UHDR" "$VERSION")
PROTECTED_BEFORE="$SAFETY/protected_before.txt"
PROTECTED_AFTER="$SAFETY/protected_after.txt"

hash_protected() {
  local out="$1"
  : > "$out"
  while IFS= read -r -d '' f; do
    skip=0
    for t in "${TARGETS[@]}"; do [[ "$f" == "$t" ]] && skip=1 && break; done
    [[ "$skip" -eq 1 ]] && continue
    printf '%s  %s\n' "$(sha "$f")" "$f" >> "$out"
  done < <(git ls-files -z app)
  sort -o "$out" "$out"
}
hash_protected "$PROTECTED_BEFORE"

echo "=== GATE 2: TEMPORARY CANDIDATES ==="
for rel in "${!PAYLOAD[@]}"; do
  dst="$CAND/$rel"
  mkdir -p "$(dirname "$dst")"
  printf '%s' "${PAYLOAD[$rel]}" | base64 -d > "$dst"
  [[ "$(sha "$dst")" == "${NEWHASH[$rel]}" ]] || fail "Candidate hash mismatch: $rel"
done

CI="$CAND/$DINIT"
CA="$CAND/$DACC"
CCJ="$CAND/$COLORJ"
CCG="$CAND/$COLORG"
CDJ="$CAND/$DENOISEJ"
CDG="$CAND/$DENOISEG"
CRJ="$CAND/$RENDERJ"
CRG="$CAND/$RENDERG"
CG="$CAND/$GAINMAP"
CU="$CAND/$UHDR"
CV="$CAND/$VERSION"

echo "=== GATE 2A: CROSS-BUILD VISUAL INVARIANT PROOF ==="
# Exact 26429 merge geometry/support restored; no 26434 motion-trust experiment.
[[ "$(sha "$CI")" == "8E0D3A176280C49D17094BC318382F9C1AF97C76FFFA85ACA7B19053F516C5C1" ]] || fail "26429 init not exact"
[[ "$(sha "$CA")" == "A7BF945D386C881A9259A9626D2A7F69AE8A5DA998387248D484D91B9A50E221" ]] || fail "26429 accumulator not exact"
! grep -q 'patchAgreement' "$CA" || fail "26434 motion-trust experiment survived"
! grep -q 'flowContinuity' "$CA" || fail "26434 flow-continuity experiment survived"
! grep -q 'referenceCeiling' "$CA" || fail "26432 hard support ceiling survived"
! grep -q 'perFrameCap' "$CA" || fail "26432 hard frame cap survived"

# COMPLETE 26430 SDR image-formation baseline, not just Render.
grep -q 'IRIS_26430_MOTION_V2_COLOR_SAFETY_ONLY' "$CCJ" || fail "26430 color Java missing"
grep -q 'IRIS_26430_SENSOR_CLIP_COLOR_SAFETY_ONLY' "$CCG" || fail "26430 color shader missing"
! grep -q 'lensShading' "$CCJ" || fail "26431 lens shading survived in recovery baseline"
! grep -q 'LensShading' "$CCG" || fail "26431 lens shading shader survived"

grep -q 'IRIS_26430_MOTION_V2_OWNED_RESIDUAL_CLEANUP' "$CDJ" || fail "26430 denoise Java missing"
grep -q 'IRIS_26430_LIGHT_SUPPORT_OWNED_RESIDUAL_CLEANUP' "$CDG" || fail "26430 denoise shader missing"

grep -q 'IRIS_26435_EXACT_26430_HEADROOM_BASE_MINUS_032EV' "$CRG" || fail "26430 tone base missing"
grep -q 'const float start=0.50;' "$CRG" || fail "26430 highlight start changed"
grep -q 'const float logShape=6.0;' "$CRG" || fail "26430 highlight shape changed"
grep -q 'linearSrgb\*=outputExposureScale;' "$CRG" || fail "Requested 0.80 scale missing"
grep -q 'OUTPUT_EXPOSURE_SCALE = 0.80f' "$CRJ" || fail "Java 0.80 scale missing"

# Conservative Ultra HDR.
grep -q 'GAINMAP_DOWNSAMPLE = 16' "$CRJ" || fail "16x gain-map downsample missing"
grep -Fq 'Math.min(3.0f, OUTPUT_EXPOSURE_SCALE * canonicalSensorWhite)' "$CRJ" || fail "3x gain cap missing"
grep -q 'IRIS_26435_LOW_FREQUENCY_HIGHLIGHT_ONLY_GAINMAP' "$CG" || fail "Low-frequency gain shader missing"
grep -q 'smoothstep(1.20,1.75,hdrY)' "$CG" || fail "Broad highlight authority gate missing"
grep -q 'meanNeighborDeltaCode' "$CRJ" || fail "Gain-map roughness telemetry missing"
grep -q 'grid12x8=' "$CRJ" || fail "Spatial gain-map grid telemetry missing"

grep -q 'MIN_HDR_TRANSITION = 1.50f' "$CU" || fail "Later HDR transition missing"
grep -Fq 'Math.min(3.0f, maxRatio)' "$CU" || fail "Attachment 3x cap missing"
grep -Fq 'Math.max(2.50f, safeMax)' "$CU" || fail "Full-HDR display threshold missing"

grep -q '^VERSION_NAME=0\.9726435$' "$CV" || fail "Candidate version name wrong"
grep -q '^VERSION_BUILD=26435$' "$CV" || fail "Candidate build wrong"

echo "candidate/source validation PASS"

echo "=== GATE 3: TEMPORARY GLSL COMPILER PROOF ==="
command -v glslangValidator >/dev/null 2>&1 || fail "glslangValidator missing"
WRAPC="$SAFETY/wrap_compute.py"
WRAPF="$SAFETY/wrap_frag.py"
cat > "$WRAPC" <<'PY'
from pathlib import Path
import re,sys
s=Path(sys.argv[1]).read_text()
s=re.sub(r'(?m)^#define\s+LAYOUT\s+//\s*\nLAYOUT\s*\n','',s,count=1)
Path(sys.argv[2]).write_text('#version 310 es\nlayout(local_size_x=8, local_size_y=8, local_size_z=1) in;\n'+s)
PY
cat > "$WRAPF" <<'PY'
from pathlib import Path
import sys
Path(sys.argv[2]).write_text('#version 310 es\n'+Path(sys.argv[1]).read_text())
PY

python3 "$WRAPC" "$CI" "$SAFETY/init.comp"
python3 "$WRAPC" "$CA" "$SAFETY/acc.comp"
python3 "$WRAPF" "$CCG" "$SAFETY/color.frag"
python3 "$WRAPF" "$CDG" "$SAFETY/denoise.frag"
python3 "$WRAPF" "$CRG" "$SAFETY/render.frag"
python3 "$WRAPF" "$CG" "$SAFETY/gain.frag"

GLSLLOG="$SAFETY/glslang_26435.txt"
{
  glslangValidator -S comp "$SAFETY/init.comp"
  glslangValidator -S comp "$SAFETY/acc.comp"
  glslangValidator -S frag "$SAFETY/color.frag"
  glslangValidator -S frag "$SAFETY/denoise.frag"
  glslangValidator -S frag "$SAFETY/render.frag"
  glslangValidator -S frag "$SAFETY/gain.frag"
} 2>&1 | tee "$GLSLLOG"

echo "Temporary-copy validation: PASS"

echo "=== GATE 4: APPLY EXACT VALIDATED CANDIDATES ==="
for rel in "${!PAYLOAD[@]}"; do
  mkdir -p "$(dirname "$rel")"
  cp "$CAND/$rel" "$rel"
done

hash_protected "$PROTECTED_AFTER"
cmp -s "$PROTECTED_BEFORE" "$PROTECTED_AFTER" || fail "Protected tracked app source changed"

# Re-prove protected reconstruction/alignment/routing unchanged.
[[ "$(sha "$RECON")" == "${CUR[$RECON]}" ]] || fail "Reconstruction Java changed"
[[ "$(sha "$ALIGN")" == "${CUR[$ALIGN]}" ]] || fail "Alignment Java changed"
[[ "$(sha "$INPUT")" == "${CUR[$INPUT]}" ]] || fail "CFA input changed"
grep -q 'targetFraction=1.0' "$HDRX" || fail "All-frame handoff changed"
grep -q 'globalGyroDiscard=false' "$HDRX" || fail "Global discard changed"

for rel in "${!NEWHASH[@]}"; do
  [[ "$(sha "$rel")" == "${NEWHASH[$rel]}" ]] || fail "Applied candidate differs: $rel"
done

git diff --check -- "${TARGETS[@]}"

echo "candidate/source validation PASS"
echo "Temporary-copy validation: PASS"
echo "PRE-BUILD SAFETY PROOF PASSED"

git diff --binary HEAD -- app > "$SAFETY/post_26435_working_tree.patch"

echo "=== GATE 5: JAVAC PROOF ==="
JLOG="$OUT/26435_JAVAC_PROOF_$STAMP.txt"
set +e
./gradlew :app:compileDebugJavaWithJavac --stacktrace 2>&1 | tee "$JLOG"
RC=${PIPESTATUS[0]}
set -e
[[ "$RC" -eq 0 ]] || fail "Javac failed; see $JLOG"
echo "JAVAC PROOF PASSED"

echo "=== GATE 6: BUILD 0.9726435 / 26435 ==="
BLOG="$OUT/build_26435_exact26430_sdr_lowfreq_hdr_$STAMP.txt"
set +e
./gradlew :app:assembleDebug --stacktrace 2>&1 | tee "$BLOG"
RC=${PIPESTATUS[0]}
set -e
[[ "$RC" -eq 0 ]] || fail "Gradle failed; see $BLOG"
grep -q 'BUILD SUCCESSFUL' "$BLOG" || fail "BUILD SUCCESSFUL not found"

APK_SRC="$(find app/build/outputs/apk -type f -name '*.apk' -printf '%T@ %p\n' | sort -nr | head -1 | cut -d' ' -f2-)"
[[ -n "$APK_SRC" && -f "$APK_SRC" ]] || fail "Built APK not found"

APK="$SRC/IrisCamera-0.9726435-26435-exact26430-sdr-lowfreq-ultrahdr-debug.apk"
find "$SRC" -maxdepth 1 -type f -name 'IrisCamera-*.apk' -delete
mv -f "$APK_SRC" "$APK"
find app/build -type f -name '*.apk' -delete

RESULT="$OUT/26435_RESULT_$STAMP.txt"
cat > "$RESULT" <<EOF
26435 EXACT 26430 SDR RECOVERY + LOW-FREQUENCY ULTRA HDR PROVENANCE

SDR recovery:
- exact 26429 direct init/accumulator
- exact 26430 Motion V2 color transform / highlight safety
- 26431 lens shading REMOVED from this controlled recovery baseline
- exact 26430 residual denoise
- exact 26430 headroom/tone mapping
- only requested 0.80 linear output scale added (~-0.322 EV)
- old Photon post graph remains bypassed
- no sharpening

Frame handling:
- all configured Motion frames remain handed to V2
- no global gyro discard
- no new 26434 motion-trust algorithm in this build
- purpose is to isolate SDR/HDR rendering causality before motion is retuned

Ultra HDR:
- actual V2 pre-tone extended-linear source retained
- 16x lower-resolution gain map
- broad 9x9 luminance-area averaging
- chroma does not drive gain
- unity through ordinary SDR body/midtones
- broad activation 1.20 -> 1.75 extended-linear luminance
- maximum gain ratio 3x
- display HDR transition starts at 1.50x
- full-HDR threshold >= 2.50x
- spatial diagnostics in log:
  meanNeighborDeltaCode
  grid12x8 hexadecimal gain codes

Safety:
Backup branch: $BACKUP
Pre patch: $SAFETY/pre_26435_working_tree.patch
Post patch: $SAFETY/post_26435_working_tree.patch
GLSL proof: $GLSLLOG
Javac proof: $JLOG
Build log: $BLOG

candidate/source validation PASS
Temporary-copy validation: PASS
PRE-BUILD SAFETY PROOF PASSED
JAVAC PROOF PASSED
BUILD SUCCESSFUL VERIFIED

APK: $APK

No commit.
No push.
dev untouched.
local.properties protected.
EOF

echo "======================================================================"
echo "26435 BUILD SUCCESSFUL"
echo "APK: $APK"
echo "RESULT: $RESULT"
echo "No commit. No push. dev untouched."
echo "======================================================================"
